insert into public.badge_defs (key, family, tier, title, description, icon, category, metric, threshold, unit, pawcoin, xp, hidden, sort) values
('prog_yavru', 'program', 1, 'Yavru Maceracı', '"Yavru Köpeğin 30 Günü" programını bitirdin', '🐾', 'egitim', 'program:yavru-kopek-30', 1, '', 0, 0, false, 70),
('prog_saglikli', 'program', 1, 'Sağlıklı Pati', '"Sağlıklı Pati" programını bitirdin', '🥗', 'saglik', 'program:saglikli-pati', 1, '', 0, 0, false, 71),
('prog_birlikte', 'program', 1, 'Mutlu Birlikte', '"Mutlu Birlikte" programını bitirdin', '💞', 'sosyal', 'program:mutlu-birlikte', 1, '', 0, 0, false, 72),
('prog_yeni_ev', 'program', 1, 'Yeni Ev', '"Yeni Ev" programını bitirdin', '🏡', 'ozel', 'program:yeni-ev', 1, '', 0, 0, false, 73),
