insert into public.programs (key, title, subtitle, description, species, tags, emoji, tint, badge_key, pawcoin, xp, sort, steps)
select x.key, x.title, x.subtitle, x.description, x.species, x.tags, x.emoji, x.tint, x.badge_key, x.pawcoin, x.xp, x.sort, x.steps
from jsonb_to_recordset($j$[
{"key":"yavru-kopek-30","sort":1,"species":["dog"],"tags":["egitim","yeni"],"emoji":"🐶","tint":"#FCE6DF","badge_key":"prog_yavru","pawcoin":200,"xp":600,
 "title":"Yavru Köpeğin 30 Günü","subtitle":"Yeni sahiplenenler için adım adım rehber",
