 "steps":[
  {"title":"Güvenli bir köşe","body":"Yavruya yatağı, su kabı ve birkaç oyuncağı olan sakin bir köşe hazırla. İlk günlerde evi yavaş yavaş keşfetmesine izin ver.","tip":"Kablo, ilaç ve küçük eşyaları yerden kaldır."},
  {"title":"Rutin kur","body":"Mama, tuvalet ve uyku saatlerini belirle ve her gün aynı tut. Yavrular rutinle daha çabuk güven kazanır."},
  {"title":"Tuvalet eğitimi başlıyor","body":"Uyandıktan, yemekten ve oyundan hemen sonra yavruyu aynı tuvalet noktasına götür. Doğru yere yaptığında hemen ödüllendir.","tip":"Kazaları cezalandırma; kokuyu enzimli temizleyiciyle gider."},
  {"title":"İsmini öğret","body":"İsmini söyle, sana baktığı anda küçük bir ödül ver. Günde birkaç kez kısa tekrarlar yeterli."},
  {"title":"Veteriner kontrolü","body":"İlk kontrol için randevu planla. Aşı takvimini, parazit korumasını ve mikroçip kaydını konuş."},
  {"title":"Kafes ya da yatak alışkanlığı","body":"Yatağını ya da kafesini güvenli bir yer haline getir: içine ödül ve oyuncak bırak, kapıyı kısa sürelerle kapat."},
  {"title":"Dokunmaya alıştır","body":"Patilerine, kulaklarına ve ağzına nazikçe dokun, her dokunuşu bir ödülle eşleştir. Veteriner ve bakım ziyaretlerini kolaylaştırır."},
  {"title":"'Otur' komutu","body":"Ödülü burnunun önünden başının üzerine doğru yavaşça kaldır; poposu yere değdiğinde 'otur' de ve ödül ver."},
  {"title":"Isırma terbiyesi","body":"Oyunda dişlerini fazla kullanırsa oyunu birkaç saniye durdur. Isırmak için ona uygun çiğneme oyuncakları sun."},
  {"title":"Yeni sesler","body":"Süpürge, kapı zili, trafik gibi sesleri düşük seviyede ve ödülle tanıştır. Korkarsa mesafeyi artır."},
  {"title":"Tasma ve koşum","body":"Evde koşumu birkaç dakika taktır, oyunla eşleştir. Tasmaya bağlıyken kısa ev içi yürüyüşler yap."},
  {"title":"Yalnız kalmayı öğret","body":"Birkaç dakikalık ayrılıklarla başla, çıkış ve dönüşleri sakin tut. Süreyi yavaş yavaş uzat."},
  {"title":"Yeni insanlar","body":"Sakin bir arkadaşının yavruyu ödülle karşılamasını iste. Yavrunun kendisinin yaklaşmasına izin ver."},
  {"title":"'Gel' komutu","body":"Yakın mesafeden ismini söyle, geldiğinde büyük bir ödül ver. Bu komut ileride hayat kurtarabilir."},
  {"title":"Kucakta şehir turu","body":"Aşıları tamamlanmadıysa kucakta ya da arabada kısa gezilerle yeni görüntüler ve kokular sun."},
  {"title":"Diş fırçalamaya giriş","body":"Parmağına köpeklere özel diş macunundan biraz alıp tattır. Birkaç gün içinde diş etine dokunmaya geç."},
  {"title":"Farklı zeminler","body":"Halı, fayans, çim, ızgara gibi farklı yüzeylerde yürümesini ödülle teşvik et."},
  {"title":"'Bekle' komutu","body":"Otururken avucunu göster, bir iki saniye beklediğinde ödül ver. Süreyi saniye saniye artır."},
  {"title":"Mama kabı nezaketi","body":"Mama kabını yere koymadan önce oturmasını bekle. Yemek yerken onu rahatsız etme; güven kazanır."},
  {"title":"Aşılı bir arkadaş","body":"Aşıları tam, sakin bir yetişkin köpekle kontrollü bir tanışma ayarla. Kısa tut ve iyi bitir."},
  {"title":"İlk dış yürüyüşler","body":"Veterinerin onay verdiyse kısa ve sakin yürüyüşlere başla. Koklamasına izin ver; mesafe değil deneyim önemli."},
  {"title":"Tasmayı çekmeden yürüme","body":"Tasma gerildiğinde dur, gevşediğinde devam et. Yanında yürüdüğünde ödül ver."},
  {"title":"'Bırak' komutu","body":"Elindeki ödülü yumruğunda tut; ilgisini çektiğinde 'bırak' de, bıraktığında diğer elinden ödül ver."},
  {"title":"Araba yolculuğu","body":"Kısa ve keyifli bir araba yolculuğu yap; varış noktası veteriner değil, sevdiği bir yer olsun."},
  {"title":"Tımar zamanı","body":"Kısa bir tarama seansı yap ve tüylerini, derisini kontrol et."},
  {"title":"Koklama oyunu","body":"Ödülleri bir havlunun kıvrımlarına sakla, bulmasına izin ver. Zihinsel yorgunluk da uyku getirir."},
  {"title":"Tekrar günü","body":"Otur, bekle, gel ve bırak komutlarını kısa ve eğlenceli bir seansla tekrar et."},
  {"title":"Kilo ve gelişim","body":"Yavrunu tart ve kaydet. Büyüme hızını veterinerinin önerileriyle karşılaştır."},
  {"title":"Aşı ve parazit takvimi","body":"Moffi'de aşı ve parazit kayıtlarının güncel olduğundan emin ol; sıradaki tarihleri kontrol et."},
  {"title":"Mezuniyet","body":"30 günü tamamladın! Yavrunun öğrendiklerini bir video ya da fotoğrafla kutla ve topluluğunla paylaş."}]},
{"key":"saglikli-pati","sort":2,"species":null,"tags":["saglik"],"emoji":"🥗","tint":"#DFF3EA","badge_key":"prog_saglikli","pawcoin":150,"xp":500,
 "title":"Sağlıklı Pati","subtitle":"Beslenme, su ve günlük bakım",
 "description":"30 günde sağlıklı alışkanlıklar: doğru porsiyon, taze su, diş, tüy ve tırnak bakımı, kilo takibi.",
 "steps":[
  {"title":"Başlangıç tartısı","body":"Hayvanını tart ve Moffi'ye kaydet. Bu, 30 günün başlangıç noktası olacak."},
  {"title":"Vücut kondisyonu","body":"Kaburgalarını eline al: ince bir tabakanın altında kolayca hissedilmeli. Yukarıdan bakınca bel çizgisi görünmeli."},
  {"title":"Porsiyonu ölç","body":"Mamayı göz kararı değil, ölçü kabı ya da tartıyla ver. Günlük miktarı veterinerinin önerisine göre ayarla."},
  {"title":"Su noktaları","body":"Evde en az iki farklı noktaya taze su koy; kapları her gün yıka."},
  {"title":"Öğün saatleri","body":"Öğünleri her gün aynı saatlerde ver ve Moffi'de işaretle. İştahtaki değişimleri erken fark edersin."},
  {"title":"Ödülleri say","body":"Gün içinde verdiğin ödülleri say; günlük kalorinin onda birini geçmemeli."},
  {"title":"Diş kontrolü","body":"Ağzına bak: diş taşı, kızarık diş eti ya da kötü koku var mı? Not al."},
  {"title":"İlk fırçalama","body":"Hayvanlara özel diş macunuyla kısa bir fırçalama dene. 30 saniye yeterli."},
  {"title":"Tüy kontrolü","body":"Tara ve deriyi kontrol et: kepek, kızarıklık ya da pire var mı?"},
  {"title":"Hareket planı","body":"Hayvanının yaşına uygun günlük hareket hedefini belirle: köpekler için yürüyüş, kediler için oyun."},
  {"title":"Tırnak kontrolü","body":"Tırnaklar yere tıkırdıyorsa kesim zamanı gelmiş demektir. Gerekirse küçük parçalar halinde kes."},
  {"title":"Kulak kontrolü","body":"Kulakların içine bak; koyu kir, koku ya da sürekli kaşıma veterinere gitme işaretidir."},
  {"title":"Göz kontrolü","body":"Gözler parlak ve akıntısız olmalı. Kızarıklık ya da sürekli sulanma varsa not al."},
  {"title":"Ara tartı","body":"İkinci tartıyı yap ve kaydet. İlk tartıyla karşılaştır."},
  {"title":"Mama etiketini oku","body":"Mamanın içeriğine ve hangi yaş grubuna uygun olduğuna bak. Sorun varsa veterinerinle konuş."},
  {"title":"Zehirli yiyecekler","body":"Evdeki tehlikeli yiyecekleri ve bitkileri gözden geçir; ulaşabileceği yerlerden kaldır."},
  {"title":"Parazit takvimi","body":"Son iç ve dış parazit uygulamasının tarihini kontrol et; gerekiyorsa sıradakini planla."},
  {"title":"Diş fırçalama alışkanlığı","body":"Bugün yine kısa bir fırçalama yap. Her gün 30 saniye, haftada bir uzun seanstan daha etkilidir."},
  {"title":"Zihinsel egzersiz","body":"Mamanın bir kısmını bulmaca oyuncağıyla ya da saklayarak ver."},
  {"title":"Su tüketimini izle","body":"Bugün kabı kaç kez doldurduğunu not et. Ani değişimleri bilmek için iyi bir referans olur."},
  {"title":"Aşı kontrolü","body":"Aşı kartını Moffi'deki kayıtlarla karşılaştır; eksik varsa ekle."},
  {"title":"Tüy dökme mevsimi","body":"Tarama sıklığını artır; tüy yumağı ve keçelenme oluşumunu önler."},
  {"title":"Üçüncü tartı","body":"Tart ve kaydet. Hedef kiloda mısınız, yoksa porsiyonu ayarlamak mı gerekiyor?"},
  {"title":"Acil durum bilgisi","body":"Moffi'de acil durum kişisini ve veteriner bilgisini doldur."},
  {"title":"Yaşa uygun bakım","body":"Hayvanının yaşına göre (yavru, yetişkin, yaşlı) bakım önerilerini oku."},
  {"title":"Dinlenme alanı","body":"Yatağını temizle, sessiz ve cereyansız bir yerde olduğundan emin ol."},
  {"title":"Ek kontrol listesi","body":"Patiler, kulaklar, gözler ve dişleri bir kez daha kontrol et; değişenleri not al."},
  {"title":"Sağlık soruları","body":"Bir sonraki veteriner ziyaretinde sormak istediklerini Moffi'deki notlara yaz."},
  {"title":"Son tartı","body":"30 günün son tartısını yap ve başlangıçla karşılaştır."},
  {"title":"Tebrikler","body":"30 günlük sağlıklı alışkanlıkları tamamladın! Bunları sürdürmek için günlük görevler seni bekliyor."}]},
{"key":"mutlu-birlikte","sort":3,"species":null,"tags":["sosyal"],"emoji":"💞","tint":"#F9E1E8","badge_key":"prog_birlikte","pawcoin":150,"xp":450,
 "title":"Mutlu Birlikte","subtitle":"Bağınızı güçlendiren 21 gün",
