  {"title":"Beden dili","body":"Bugün mutlu, rahat ve gergin olduğu anlardaki beden dilini gözlemle."},
  {"title":"Birlikte keşif","body":"Köpeğinle yeni bir rota yürü; kedinle evde yeni bir köşe keşfet."},
  {"title":"Bir numara öğret","body":"Basit bir numara seç: pati ver, dön ya da 'beşlik'. Kısa seanslarla çalış."},
  {"title":"Fotoğraf günü","body":"Güzel bir anınızı fotoğrafla ve albüme ekle."},
  {"title":"Topluluğa merhaba","body":"Keşfet'te hayvanını etiketleyerek bir anı paylaş."},
  {"title":"Arkadaşını davet et","body":"Hayvan sahibi bir arkadaşını Moffi'ye davet et ya da takipleş."},
  {"title":"Ortak hedef","body":"Bir arkadaşınla Birlikte bölümünden haftalık ortak hedef oluştur."},
  {"title":"Koklama ya da avcılık","body":"Köpeğinle koklama yürüyüşü yap; kedinle av oyunu oyna."},
  {"title":"Masaj ve dokunuş","body":"Sevdiği yerlerden nazikçe sev; rahatlamış bir hayvan güvenini gösterir."},
  {"title":"Numara tekrarı","body":"Öğrendiği numarayı farklı bir odada tekrar et."},
  {"title":"Birlikte dinlen","body":"Bugün acelesiz bir gün: kısa yürüyüş ya da oyun, sonra birlikte dinlenme."},
  {"title":"Yeni bir kişiyle tanış","body":"Sakin bir arkadaşın ödülle tanışsın; hayvanın yaklaşmayı kendi seçsin."},
  {"title":"Topluluğa destek","body":"Yakınındaki kayıp ve sahiplendirme ilanlarına göz at; bir ilanı paylaşmak bir hayvanın yuvasına dönmesini sağlayabilir."},
  {"title":"Ortak hedefi kontrol et","body":"Arkadaşlarınla hedefinizde nerede olduğunuza bak; bir motivasyon mesajı gönder."},
  {"title":"Oyun icat et","body":"Evdeki malzemelerle yeni bir oyun icat et: kartondan tünel ya da bardak altında ödül bulma."},
  {"title":"Teşekkür günü","body":"Bugün ona en sevdiği ödülü ver ve birlikte en sevdiği şeyi yapın."},
  {"title":"Anı albümü","body":"Bu 21 günde çektiğin fotoğraflardan birini anı olarak kaydet."},
  {"title":"Birlikte mutlu","body":"21 günü tamamladınız! Bağınızı güçlendiren bu alışkanlıkları sürdürmeye devam et."}]},
{"key":"yeni-ev","sort":4,"species":null,"tags":["yeni"],"emoji":"🏡","tint":"#F3EBDD","badge_key":"prog_yeni_ev","pawcoin":100,"xp":350,
 "title":"Yeni Ev","subtitle":"Taşınma ve yeni ortama alışma",
