 "steps":[
  {"title":"Güvenli oda","body":"Yatağı, suyu, maması ve kedi için kum kabı olan sakin bir oda hazırla. İlk günler burada geçsin."},
  {"title":"Evi güvenli hale getir","body":"Kabloları topla, pencerelere güvenlik önlemi al, zehirli bitkileri ve ilaçları kaldır."},
  {"title":"Tanıdık koku","body":"Eski evden ya da barınaktan gelen bir battaniye veya oyuncağı yatağına koy."},
  {"title":"Rutin","body":"Mama, oyun ve uyku saatlerini belirle; her gün aynı saatlerde tekrarla."},
  {"title":"Keşfe izin ver","body":"Hazır olduğunda evin diğer bölümlerini kendi hızında keşfetsin; zorlama."},
  {"title":"Künye ve çip","body":"Künyeye yeni adres ve telefonu ekle; çip kaydındaki bilgileri güncelle."},
  {"title":"Veteriner seç","body":"Yeni evine yakın bir veteriner kliniği belirle ve ilk kontrol için randevu planla."},
  {"title":"Diğer hayvanlarla tanışma","body":"Evde başka hayvan varsa önce koku ile tanıştır: yatak değiş tokuşu yap, sonra kapı arkasından kısa görüşmeler."},
  {"title":"Mahalleyi tanı","body":"Köpeğinle kısa yürüyüşlerle mahalleyi keşfet; kedinle pencereden manzarayı birlikte izle."},
  {"title":"Yalnız kalma","body":"Kısa ayrılıklarla başla; çıkış ve dönüşleri sakin tut."},
  {"title":"İştah ve tuvalet","body":"Yeme, içme ve tuvalet alışkanlıklarını gözlemle. Üç günü geçen iştahsızlıkta veterinere danış."},
  {"title":"Saklanma yerleri","body":"Kediler için yüksek ve kapalı saklanma yerleri, köpekler için sakin bir köşe ekle."},
  {"title":"Komşular ve sesler","body":"Yeni seslere ödülle alışmasını sağla: asansör, kapı, trafik."},
  {"title":"Hoş geldin","body":"14 günü tamamladınız! Yeni yuvanızda mutlu günler."}]},
{"key":"mutlu-kedi-evi","sort":5,"species":["cat"],"tags":["egitim","saglik"],"emoji":"🐈","tint":"#FCE6DF","badge_key":"prog_kedi","pawcoin":100,"xp":350,
