  {"title":"Tüy ve diş","body":"Kısa bir tarama ve diş kontrolü yap; değişiklikleri not al."},
  {"title":"Pencere keyfi","body":"Pencere önüne bir minder koy; dışarıyı izlemek kediler için eğlencedir."},
  {"title":"Zehirli bitkiler","body":"Evdeki bitkileri kontrol et; zambakları hemen çıkar."},
  {"title":"Oyuncak rotasyonu","body":"Oyuncakların yarısını kaldır; birkaç gün sonra değiştir, her seferinde yeni gibi gelir."},
  {"title":"Mutlu kedi","body":"14 günü tamamladın! Kedinin ihtiyaçlarını artık çok daha iyi tanıyorsun."}]}
]$j$::jsonb) as x(key text, title text, subtitle text, description text, species text[], tags text[], emoji text, tint text,
                  badge_key text, pawcoin int, xp int, sort int, steps jsonb)
on conflict (key) do update set title = excluded.title, subtitle = excluded.subtitle, description = excluded.description,
    species = excluded.species, tags = excluded.tags, emoji = excluded.emoji, tint = excluded.tint, badge_key = excluded.badge_key,
    pawcoin = excluded.pawcoin, xp = excluded.xp, sort = excluded.sort, steps = excluded.steps;
